export const premiumProductById = (id:string) => premiumCatalog.find(p=>p.id===id);
export const premiumByRoom = (room:string) => premiumCatalog.filter(p=>p.room===room);
export const premiumRelated = (product:PremiumProduct, limit=4) => premiumCatalog.filter(p=>p.id!==product.id && p.relatedGroup===product.relatedGroup).slice(0,limit).length ? premiumCatalog.filter(p=>p.id!==product.id && p.relatedGroup===product.relatedGroup).slice(0,limit) : premiumCatalog.filter(p=>p.id!==product.id && p.room===product.room).slice(0,limit);
export const premiumFormatPrice = (n:number) => new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",minimumFractionDigits:0,maximumFractionDigits:0}).format(n);